var firebaseHandlePromise = null;
function getFirebase() {
	if (!firebaseHandlePromise) firebaseHandlePromise = (async () => {
		try {
			const config = await __vitePreload(() => import("./config-BYrUtV0g.js"), []);
			const db = config.db;
			if (!config.isFirebaseConfigured || !db) return null;
			return {
				db,
				auth: config.auth
			};
		} catch {
			return null;
		}
	})();
	return firebaseHandlePromise;
}
var COMPLETED_MODULES_KEY = "insco_academy_completed_modules";
var COMPLETED_TOPICS_KEY = "insco_academy_completed_topics_v1";
var QUIZ_RESULTS_KEY = "insco_academy_quiz_results_v1";
function getCompletedModules() {
	try {
		const raw = localStorage.getItem(COMPLETED_MODULES_KEY);
		return raw ? JSON.parse(raw) : {};
	} catch {
		return {};
	}
}
function markModuleCompleted(moduleId, score = 100) {
	try {
		const completed = getCompletedModules();
		completed[moduleId] = true;
		localStorage.setItem(COMPLETED_MODULES_KEY, JSON.stringify(completed));
		syncActiveUserModuleCompletion(moduleId, true);
		const results = getQuizResults();
		results[moduleId] = {
			moduleId,
			score,
			completedAt: (/* @__PURE__ */ new Date()).toISOString(),
			passed: score >= 75
		};
		localStorage.setItem(QUIZ_RESULTS_KEY, JSON.stringify(results));
		syncModuleToFirestore(moduleId, score);
		window.dispatchEvent(new CustomEvent("insco_progress_updated", { detail: {
			moduleId,
			score
		} }));
		window.dispatchEvent(new CustomEvent("insco_user_progress_updated", { detail: {
			moduleId,
			completed: true
		} }));
	} catch (e) {
		console.error("Failed to mark module completed:", e);
	}
}
function getCompletedTopics() {
	try {
		const raw = localStorage.getItem(COMPLETED_TOPICS_KEY);
		return raw ? JSON.parse(raw) : {};
	} catch {
		return {};
	}
}
async function toggleTopicCompleted(moduleId, topicText, disciplineId) {
	try {
		const map = getCompletedTopics();
		const currentList = new Set(map[moduleId] || []);
		let completed = false;
		if (currentList.has(topicText)) {
			currentList.delete(topicText);
			completed = false;
		} else {
			currentList.add(topicText);
			completed = true;
		}
		map[moduleId] = Array.from(currentList);
		localStorage.setItem(COMPLETED_TOPICS_KEY, JSON.stringify(map));
		window.dispatchEvent(new CustomEvent("insco_topic_progress_updated", { detail: {
			moduleId,
			topicText,
			completed,
			totalCompleted: map[moduleId].length
		} }));
		await syncTopicsToFirestore(moduleId, map[moduleId], disciplineId);
		return {
			completed,
			totalCompleted: map[moduleId].length
		};
	} catch (err) {
		console.error("Error toggling topic completed:", err);
		return {
			completed: false,
			totalCompleted: 0
		};
	}
}
async function syncTopicsToFirestore(moduleId, topics, disciplineId) {
	const firebase = await getFirebase();
	if (!firebase?.db) return {
		synced: false,
		error: "Cloud sync is not configured; progress stays local"
	};
	try {
		const { doc, setDoc, serverTimestamp } = await __vitePreload(async () => {
			const { doc, setDoc, serverTimestamp } = await import("./index.esm-DMKt96Uk.js").then((n) => n.t);
			return {
				doc,
				setDoc,
				serverTimestamp
			};
		}, __vite__mapDeps([0,1]));
		const userId = firebase.auth?.currentUser?.uid || getLocalUserId();
		await setDoc(doc(firebase.db, "user_module_progress", `${userId}_${moduleId}`), {
			userId,
			moduleId,
			disciplineId: disciplineId || "general",
			completedTopics: topics,
			completedCount: topics.length,
			updatedAt: serverTimestamp(),
			clientTimestamp: (/* @__PURE__ */ new Date()).toISOString()
		}, { merge: true });
		return {
			synced: true,
			lastSyncedAt: (/* @__PURE__ */ new Date()).toLocaleTimeString()
		};
	} catch (error) {
		console.warn("Firestore sync background notice (using local storage):", error?.message);
		return {
			synced: false,
			error: error?.message
		};
	}
}
async function syncModuleToFirestore(moduleId, score) {
	const firebase = await getFirebase();
	if (!firebase?.db) return;
	try {
		const { doc, setDoc, serverTimestamp } = await __vitePreload(async () => {
			const { doc, setDoc, serverTimestamp } = await import("./index.esm-DMKt96Uk.js").then((n) => n.t);
			return {
				doc,
				setDoc,
				serverTimestamp
			};
		}, __vite__mapDeps([0,1]));
		const userId = firebase.auth?.currentUser?.uid || getLocalUserId();
		await setDoc(doc(firebase.db, "user_module_progress", `${userId}_${moduleId}`), {
			userId,
			moduleId,
			isPassed: score >= 75,
			score,
			unlockedCertificate: score >= 75,
			completedAt: serverTimestamp()
		}, { merge: true });
	} catch (e) {
		console.warn("Firestore module sync notice:", e);
	}
}
function getLocalUserId() {
	let uid = localStorage.getItem("insco_local_student_uid");
	if (!uid) {
		uid = "student_" + Math.random().toString(36).substring(2, 10);
		localStorage.setItem("insco_local_student_uid", uid);
	}
	return uid;
}
function getQuizResults() {
	try {
		const raw = localStorage.getItem(QUIZ_RESULTS_KEY);
		return raw ? JSON.parse(raw) : {};
	} catch {
		return {};
	}
}
