/**
* Classifies any logged 3D simulation defect into one of the 6 core welding error categories.
*/
function classifyDiscoveredDefectBucket(entry) {
	const catId = entry.catalogDefectId;
	if (catId === "isolated_pore" || catId === "porosity_cluster" || catId === "wormhole_porosity") return "porosity";
	if (catId === "lack_of_fusion" || catId === "interpass_lof" || catId === "root_lof") return "lack_of_fusion";
	if (catId === "slag_inclusion" || catId === "tungsten_inclusion") return "slag_inclusions";
	if (catId === "incomplete_penetration" || catId === "root_concavity") return "incomplete_penetration";
	if (catId === "root_crack" || catId === "transverse_crack" || catId === "haz_underbead_crack" || catId === "crater_star_crack") return "cracks";
	if (catId === "toe_undercut" || catId === "base_lamination") return "undercut_lamination";
	const hay = `${entry.codeSymbol} ${entry.type.en}`.toLowerCase();
	if (hay.includes("por")) return "porosity";
	if (hay.includes("lof") || hay.includes("fusion")) return "lack_of_fusion";
	if (hay.includes("slag") || hay.includes("tungsten") || hay.includes("sl-")) return "slag_inclusions";
	if (hay.includes("lop") || hay.includes("penetration")) return "incomplete_penetration";
	if (hay.includes("undercut") || hay.includes("lam")) return "undercut_lamination";
	return "cracks";
}
function aggregateDefectFrequencyByCategory(entries, metricMode = "unique_defects") {
	const grouped = /* @__PURE__ */ new Map();
	for (const cat of WELDING_ERROR_CATEGORIES) grouped.set(cat.id, []);
	for (const entry of entries) {
		const bucketId = classifyDiscoveredDefectBucket(entry);
		grouped.get(bucketId)?.push(entry);
	}
	const totalMetric = entries.reduce((acc, item) => acc + (metricMode === "unique_defects" ? 1 : Math.max(1, item.hitCount)), 0);
	return WELDING_ERROR_CATEGORIES.map((cat) => {
		const list = grouped.get(cat.id) ?? [];
		const uniqueCount = list.length;
		const scanHitCount = list.reduce((sum, e) => sum + Math.max(1, e.hitCount), 0);
		const activeVal = metricMode === "unique_defects" ? uniqueCount : scanHitCount;
		const avgSignalPct = list.length > 0 ? Number((list.reduce((s, e) => s + e.peakSignalPct, 0) / list.length).toFixed(1)) : 0;
		const sharePct = totalMetric > 0 ? Math.round(activeVal / totalMetric * 100) : 0;
		return {
			...cat,
			uniqueCount,
			scanHitCount,
			avgSignalPct,
			sharePct,
			matchingEntries: list
		};
	});
}
