function quiz(id, questionAr, questionEn, options, answer, explanationAr, explanationEn) {
	return {
		id,
		question: t(questionAr, questionEn),
		options: options.map(([ar, en]) => t(ar, en)),
		answer,
		explanation: t(explanationAr, explanationEn)
	};
}
