//#region src/ai/corpus.ts
/**
* The searchable corpus: every textbook page and every course lesson, built in
* memory from the same data the reader and the EDB/EPUB builders use.
*
* Keeping one builder means a page added to a textbook is searchable and
* citable immediately — there is no second index to forget to update.
*
* Runs in the browser and in Node (no imports beyond the data modules).
*/
function join(parts) {
	return parts.filter((part) => Boolean(part && part.trim())).join("\n");
}
function textbookDocuments() {
	const documents = [];
	for (const book of NDT_TEXTBOOKS) for (const page of book.pages) {
		const keyPointsAr = (page.keyPointsAr ?? []).join("\n");
		const keyPointsEn = (page.keyPointsEn ?? []).join("\n");
		const quizAr = page.quizQuestion ? join([
			page.quizQuestion.questionAr,
			page.quizQuestion.explanationAr,
			(page.quizQuestion.optionsAr ?? []).join("\n")
		]) : "";
		const quizEn = page.quizQuestion ? join([
			page.quizQuestion.questionEn,
			page.quizQuestion.explanationEn,
			(page.quizQuestion.optionsEn ?? []).join("\n")
		]) : "";
		documents.push({
			id: `${book.id}#p${page.pageNumber}`,
			kind: "textbook",
			bookId: book.id,
			pageNumber: page.pageNumber,
			title: {
				ar: page.pageTitleAr,
				en: page.pageTitleEn
			},
			section: {
				ar: page.chapterTitleAr,
				en: page.chapterTitleEn
			},
			discipline: book.discipline,
			text: {
				ar: join([
					page.contentAr,
					keyPointsAr,
					page.formula?.descriptionAr,
					quizAr
				]),
				en: join([
					page.contentEn,
					keyPointsEn,
					page.formula?.descriptionEn,
					quizEn
				])
			}
		});
	}
	return documents;
}
function courseDocuments() {
	const documents = [];
	for (const course of NDE_ED_COURSES) {
		documents.push({
			id: `${course.id}#overview`,
			kind: "course",
			bookId: course.id,
			courseId: course.id,
			title: course.title,
			section: course.subtitle,
			discipline: course.disciplineId,
			text: {
				ar: join([
					course.description.ar,
					course.outcomes.map((outcome) => outcome.ar).join("\n"),
					course.prerequisites.ar
				]),
				en: join([
					course.description.en,
					course.outcomes.map((outcome) => outcome.en).join("\n"),
					course.prerequisites.en
				])
			}
		});
		for (const lesson of course.lessons) documents.push({
			id: `${course.id}#${lesson.id}`,
			kind: "lesson",
			bookId: course.id,
			courseId: course.id,
			lessonId: lesson.id,
			title: lesson.title,
			section: course.title,
			discipline: course.disciplineId,
			text: {
				ar: join([
					lesson.summary.ar,
					lesson.objectives.map((item) => item.ar).join("\n"),
					lesson.sections.map((section) => join([section.heading.ar, section.body.ar])).join("\n"),
					join([lesson.workedExample.prompt.ar, lesson.workedExample.solution.ar]),
					join([lesson.exercise.prompt.ar, lesson.exercise.answer.ar]),
					join([lesson.quiz.question.ar, lesson.quiz.explanation.ar])
				]),
				en: join([
					lesson.summary.en,
					lesson.objectives.map((item) => item.en).join("\n"),
					lesson.sections.map((section) => join([section.heading.en, section.body.en])).join("\n"),
					join([lesson.workedExample.prompt.en, lesson.workedExample.solution.en]),
					join([lesson.exercise.prompt.en, lesson.exercise.answer.en]),
					join([lesson.quiz.question.en, lesson.quiz.explanation.en])
				])
			}
		});
	}
	return documents;
}
var cache = null;
/** Built once per process (or per tab); the source data is static. */
function getCorpus() {
	if (!cache) cache = [...textbookDocuments(), ...courseDocuments()];
	return cache;
}
var statsCache = null;
function getCorpusStats() {
	if (statsCache) return statsCache;
	const documents = getCorpus();
	const books = /* @__PURE__ */ new Set();
	let pages = 0;
	let courses = 0;
	let lessons = 0;
	for (const document of documents) if (document.kind === "textbook") {
		pages += 1;
		books.add(document.bookId);
	} else if (document.kind === "course") courses += 1;
	else lessons += 1;
	statsCache = {
		documents: documents.length,
		pages,
		courses,
		lessons,
		books: books.size
	};
	return statsCache;
}
function targetOf(document) {
	if (document.kind === "textbook") return {
		tab: "edb",
		bookId: document.bookId,
		pageNumber: document.pageNumber
	};
	return {
		tab: "courses",
		courseId: document.courseId ?? document.bookId
	};
}
