function formatAttemptTimestamp(iso, language) {
	const parsed = new Date(iso);
	if (Number.isNaN(parsed.getTime())) return iso;
	try {
		return new Intl.DateTimeFormat(language === "ar" ? "ar-EG" : "en-GB", {
			year: "numeric",
			month: "short",
			day: "2-digit",
			hour: "2-digit",
			minute: "2-digit",
			second: "2-digit",
			hour12: false
		}).format(parsed);
	} catch {
		return iso.replace("T", " ").slice(0, 19);
	}
}
